package org.millenaire.common.entity;import org.millenaire.common.village.Building;import org.millenaire.common.utilities.Point;import net.minecraft.world.level.block.state.BlockState;public class MillVillager {public net.minecraft.world.level.Level level;public Building house=new Building(),destination=new Building(),inventory=new Building();public Point point;public Building getHouse(){return house;}public Building getGoalBuildingDest(){return destination;}public Point getGoalDestPoint(){return point;}public int countInv(BlockState s){return inventory.countGoods(s);}public int takeFromInv(BlockState s,int n){return inventory.takeGoods(s,n);}}